    botTitle: L('Skjetten — hjelpebot', 'Skjetten — help bot', 'Skjetten — hjælpebot', 'Skjetten — hjälprobot', 'Skjetten — ohjebotti', 'Skjetten — bot pomocy', 'Skjetten — bot de ayuda', 'Skjetten — bot d’aide', 'Skjetten — Hilfsbot'),
    botGreet: L('Hei! Jeg er Skjetten. Spør om hvilken som helst modul, innstilling eller feil — jeg svarer med tips og steg. Etter noen spørsmål kan jeg foreslå supportsak.', 'Hi! I’m Skjetten. Ask about any module, setting or bug — I’ll reply with tips and steps. After a few questions I may suggest a support ticket.', 'Hej! Jeg er Skjetten. Spørg om moduler, indstillinger eller fejl — jeg svarer med tip og trin.', 'Hej! Jag är Skjetten. Fråga om moduler, inställningar eller fel — jag svarar med tips och steg.', 'Hei! Olen Skjetten. Kysy moduleista, asetuksista tai virheistä — vastaan vinkeillä.', 'Cześć! Jestem Skjetten. Pytaj o moduły, ustawienia lub błędy — odpowiem wskazówkami.', '¡Hola! Soy Skjetten. Pregunta por módulos, ajustes o errores — respondo con tips y pasos.', 'Salut ! Je suis Skjetten. Demande des modules, réglages ou bugs — je réponds avec des conseils.', 'Hallo! Ich bin Skjetten. Frag nach Modulen, Einstellungen oder Fehlern — ich antworte mit Tipps.'),
    botGreetChild: L('Hei! Jeg er Skjetten — jeg hjelper deg i ProTop. Spør om kalender, gjøremål eller hvor du trykker. Hvis du står fast, kan vi sende en sak til en voksen.', 'Hi! I’m Skjetten — I help you in ProTop. Ask about calendar, tasks or where to tap. If you’re stuck, we can send a note for a grown-up.', 'Hej! Jeg er Skjetten — jeg hjælper dig i ProTop.', 'Hej! Jag är Skjetten — jag hjälper dig i ProTop.', 'Hei! Olen Skjetten — autan sinua ProTopissa.', 'Cześć! Jestem Skjetten — pomagam w ProTop.', '¡Hola! Soy Skjetten — te ayudo en ProTop.', 'Salut ! Je suis Skjetten — je t’aide dans ProTop.', 'Hallo! Ich bin Skjetten — ich helfe dir in ProTop.'),
    botGreetTeen: L('Hei! Skjetten her. Spør om apper, innstillinger eller feil — jeg gir konkrete steg. Etter noen runder kan vi åpne supportsak.', 'Hi! Skjetten here. Ask about apps, settings or bugs — I’ll give concrete steps. After a few rounds we can open a support ticket.', 'Hej! Skjetten her. Spørg om apps, indstillinger eller fejl.', 'Hej! Skjetten här. Fråga om appar, inställningar eller fel.', 'Hei! Skjetten täällä. Kysy apeista, asetuksista tai virheistä.', 'Cześć! Tu Skjetten. Pytaj o apki, ustawienia lub błędy.', '¡Hola! Skjetten aquí. Pregunta por apps, ajustes o errores.', 'Salut ! Skjetten ici. Demande apps, réglages ou bugs.', 'Hallo! Skjetten hier. Frag nach Apps, Einstellungen oder Fehlern.'),
    botPlaceholder: L('Skriv spørsmålet ditt…', 'Type your question…', 'Skriv dit spørgsmål…', 'Skriv din fråga…', 'Kirjoita kysymyksesi…', 'Napisz pytanie…', 'Escribe tu pregunta…', 'Écris ta question…', 'Schreib deine Frage…'),
    botFallback: L('Beklager — jeg klarte ikke svare akkurat nå. Prøv igjen, eller kontakt support.', 'Sorry — I couldn’t answer just now. Try again, or contact support.', 'Beklager — jeg kunne ikke svare lige nu. Prøv igen, eller kontakt support.', 'Tyvärr — jag kunde inte svara just nu. Försök igen eller kontakta support.', 'Anteeksi — en voinut vastata juuri nyt. Yritä uudelleen tai ota yhteyttä tukeen.', 'Przepraszam — nie udało się odpowiedzieć. Spróbuj ponownie lub skontaktuj się z pomocą.', 'Lo siento — no pude responder ahora. Inténtalo de nuevo o contacta soporte.', 'Désolé — je n’ai pas pu répondre. Réessaie ou contacte le support.', 'Sorry — ich konnte gerade nicht antworten. Bitte erneut versuchen oder Support kontaktieren.'),
    suggestSupport: L('Fikk du ikke svar? Kontakt support med saksnummer', 'Still stuck? Contact support for a ticket number', 'Fik du ikke svar? Kontakt support', 'Fick du inget svar? Kontakta support', 'Etkö saanut vastausta? Ota yhteyttä tukeen', 'Brak odpowiedzi? Skontaktuj się z pomocą', '¿Sin respuesta? Contacta soporte', 'Pas de réponse ? Contacte le support', 'Keine Antwort? Support kontaktieren'),
