    userNotFound: L('Fant ingen bruker med det brukernavnet, e-posten eller telefonnummeret. Bruk @brukernavn (ikke fornavn), e-post eller +47…', 'No user found with that username, email or phone. Use @username (not first name), email or +47…', 'Ingen bruger fundet. Brug @brugernavn (ikke fornavn), e-mail eller +47…', 'Ingen användare hittades. Använd @användarnamn (inte förnamn), e-post eller +47…', 'Käyttäjää ei löytynyt. Käytä @käyttäjänimeä (ei etunimeä), sähköpostia tai +47…', 'Nie znaleziono użytkownika. Użyj @nazwy (nie imienia), e-maila lub +47…', 'No se encontró el usuario. Usa @usuario (no el nombre), email o +47…', 'Aucun utilisateur trouvé. Utilise @identifiant (pas le prénom), e-mail ou +47…', 'Kein Nutzer gefunden. Nutze @benutzername (nicht den Vornamen), E-Mail oder +47…'),
    inviteFailed: L('Kunne ikke sende venneforespørsel. Prøv igjen.', 'Could not send friend request. Try again.', 'Kunne ikke sende venneanmodning. Prøv igen.', 'Kunde inte skicka vänförfrågan. Försök igen.', 'Kaveripyyntöä ei voitu lähettää. Yritä uudelleen.', 'Nie udało się wysłać zaproszenia. Spróbuj ponownie.', 'No se pudo enviar la solicitud. Inténtalo de nuevo.', 'Impossible d’envoyer la demande. Réessaie.', 'Freundschaftsanfrage fehlgeschlagen. Bitte erneut versuchen.'),
    alreadyFriends: L('Dere er allerede venner.', 'You are already friends.', 'I er allerede venner.', 'Ni är redan vänner.', 'Olette jo kavereita.', 'Jesteście już znajomymi.', 'Ya sois amigos.', 'Vous êtes déjà amis.', 'Ihr seid schon Freunde.'),
    invitePending: L('En forespørsel venter allerede.', 'A request is already pending.', 'En anmodning afventer allerede.', 'En förfrågan väntar redan.', 'Pyyntö on jo odottamassa.', 'Zaproszenie już czeka.', 'Ya hay una solicitud pendiente.', 'Une demande est déjà en attente.', 'Eine Anfrage wartet bereits.'),
    cannotInviteSelf: L('Du kan ikke invitere deg selv.', 'You cannot invite yourself.', 'Du kan ikke invitere dig selv.', 'Du kan inte bjuda in dig själv.', 'Et voi kutsua itseäsi.', 'Nie możesz zaprosić siebie.', 'No puedes invitarte a ti mismo.', 'Tu ne peux pas t’inviter.', 'Du kannst dich nicht selbst einladen.'),
