    requestFrom: L('{name} vil gjerne bli venn med deg på ProTop.', '{name} wants to be your friend on ProTop.', '{name} vil gerne være ven med dig på ProTop.', '{name} vill bli vän med dig på ProTop.', '{name} haluaisi olla kaverisi ProTopissa.', '{name} chce być twoim znajomym w ProTop.', '{name} quiere ser tu amigo en ProTop.', '{name} veut être ton ami sur ProTop.', '{name} möchte dein Freund auf ProTop sein.'),
    acceptedBody: L('Dere er nå venner. De får ikke tilgang til familien din.', 'You are now friends. They do not get family access.', 'I er nu venner. De får ikke adgang til din familie.', 'Ni är nu vänner. De får inte familjeåtkomst.', 'Olette nyt kavereita. He eivät saa perheeseen pääsyä.', 'Jesteście teraz znajomymi. Bez dostępu do rodziny.', 'Ahora sois amigos. Sin acceso familiar.', 'Vous êtes maintenant amis. Sans accès famille.', 'Ihr seid jetzt Freunde. Ohne Familienzutritt.'),
    declinedBody: L('Forespørselen er avslått.', 'The request was declined.', 'Anmodningen er afvist.', 'Förfrågan avböjdes.', 'Pyyntö hylättiin.', 'Zaproszenie odrzucono.', 'Se rechazó la solicitud.', 'La demande a été refusée.', 'Die Anfrage wurde abgelehnt.'),
    alreadyHandled: L('Denne forespørselen er allerede besvart.', 'This request was already answered.', 'Denne anmodning er allerede besvaret.', 'Denna förfrågan är redan besvarad.', 'Tähän pyyntöön on jo vastattu.', 'To zaproszenie już obsłużono.', 'Esta solicitud ya se respondió.', 'Cette demande a déjà été traitée.', 'Diese Anfrage wurde bereits beantwortet.'),
